import { Component, ComponentInterface, Element, h, Host, Prop, Watch } from '@stencil/core';
import { filter, fromEvent, merge, Observable, Subject, switchMap, takeUntil, timer } from 'rxjs';
import { PopoverPlacement } from '../../types';
import { FocusHelper } from '../../utils/focus-helper';

/**
 * @slot default - default slot for the content of the menu component (usually groupui-menu-items's and groupui-menu-groups's)
 * @slot trigger - named slot 'trigger', used for the element that will trigger the menu (usually a groupui-button)
 */
@Component({
  tag: 'groupui-menu',
  styleUrl: 'menu.scss',
  shadow: true,
})
export class Menu implements ComponentInterface {
  /**
   * toggles visibility
   */
  @Prop({ reflect: true, mutable: true }) visible: boolean = false;

  /**
   * content width is 100% of trigger element width
   */
  @Prop({ reflect: true }) readonly fullWidth: boolean;

  /**
   * set max-height for the container (e.g. "200px")
   */
  @Prop({ reflect: true }) readonly maxHeight: string = 'none';

  /**
   * content placement relative to the trigger element.
   * for a list of possible placements check https://popper.js.org/docs/v2/constructors/#options
   */
  @Prop({ reflect: true }) readonly placement: PopoverPlacement = 'bottom-start';

  /**
   * content offset relative to the trigger element (in pixel)
   */
  @Prop({ reflect: true }) readonly offset: number = 0;

  /**
   * minimum width of the menu content (e.g. "200px")
   * if not set, the minWidth is determined by the content
   */
  @Prop({ reflect: true }) readonly minWidth: string = 'none';

  @Element() host: HTMLElement;

  private delayBeforeCloseOnHover = 160;
  private delayBeforeOpenOnHover = 480;

  private outsideClick = new Observable<Event>();

  private defaultSlotChange = new Subject<void>();
  private menuGroupsSlotChanges = new Observable<Event>();
  private destroy = new Subject<void>();

  private menuJustOpenedWithKeyboard = false;
  private menuJustOpenedWithHover = false;

  @Watch('visible')
  onVisibleChange() {
    this.updateTriggerElementForParentMenu();

    if (this.visible && this.isSubmenu()) {
      this.closeAllSiblingMenus();
      return;
    }
    if (!this.visible && this.isSubmenu()) {
      this.focusMenuItemsContainerOfParentMenu();
    }
  }

  private updateTriggerElementForParentMenu() {
    if (!this.isSubmenu()) return;

    if (this.visible) {
      this.triggerElementForParentMenu()?.classList.add('hover');
    } else {
      this.triggerElementForParentMenu()?.classList.remove('hover');
    }
  }

  private triggerElementForParentMenu(): HTMLGroupuiMenuItemElement {
    return this.host.querySelector(':scope > groupui-menu-item[slot="trigger"]');
  }

  componentDidLoad() {
    this.createDefaultSlotChangeListener();
    this.createMenuGroupSlotChangeListener();

    this.subscribeToTriggerClick();
    this.subscribeToOutsideClicks();
    this.subscribeToKeydownEvents();
    this.subscribeToDefaultSlotChange();
    this.subscribeToCombinedSlotChanges();

    if (this.isSubmenu()) {
      this.subscribeToTriggerOpenKeyDowns();
      this.subscribeToTriggerHover();
      this.subscribeToMenuMouseLeave();
    }

    this.updateFirstItem();
    this.updateLastItem();
    this.updateTriggerElementForParentMenu();
  }

  private createDefaultSlotChangeListener() {
    fromEvent(this.defaultSlot(), 'slotchange')
      .pipe(takeUntil(this.destroy))
      .subscribe(() => {
        this.defaultSlotChange.next();
      });
  }

  private subscribeToDefaultSlotChange() {
    this.defaultSlotChange.pipe(takeUntil(this.destroy)).subscribe(() => {
      this.createMenuGroupSlotChangeListener();
      this.subscribeToCombinedSlotChanges();
    });
  }

  private createMenuGroupSlotChangeListener() {
    this.menuGroupsSlotChanges = merge(
      ...this.menuGroups().map((group) => {
        return fromEvent(group, 'MenuGroupOnSlotChange');
      })
    ).pipe(takeUntil(merge(this.destroy, this.defaultSlotChange)));
  }

  private subscribeToCombinedSlotChanges() {
    merge(this.menuGroupsSlotChanges, this.defaultSlotChange)
      .pipe(takeUntil(this.destroy))
      .subscribe(() => {
        this.resetFirstAndLastItem();
        this.updateFirstItem();
        this.updateLastItem();
      });
  }

  private resetFirstAndLastItem() {
    this.menuItems().forEach((item) => {
      item.classList.remove('first');
      item.classList.remove('last');
    });
  }

  private updateFirstItem() {
    const menuItems = this.menuItems();
    if (menuItems.length === 0) return;

    const first = menuItems[0];
    if (this.itemIsInGroupWithoutLabel(first)) {
      first.classList.add('first');
    }
  }

  private itemIsInGroupWithoutLabel(item: HTMLElement): boolean {
    const group = item.closest('groupui-menu-group');
    return group === null || group.shadowRoot.querySelector('slot[name="label"]') === null;
  }

  private updateLastItem() {
    const menuItems = this.menuItems();
    if (menuItems.length === 0) return;

    const last = menuItems[menuItems.length - 1];
    last.classList.add('last');
  }

  private subscribeToKeydownEvents() {
    fromEvent(this.host, 'keydown')
      .pipe(filter(() => this.visible))
      .pipe(takeUntil(this.destroy))
      .subscribe((event: KeyboardEvent) => {
        this.handleKeyDown(event);
      });
  }

  disconnectedCallback() {
    this.destroy.next();
    this.destroy.complete();
  }

  private handleOutsideClick = (event: Event) => {
    if (this.visible && !event.composedPath().includes(this.host)) {
      this.visible = false;
    }
  };

  private closeAllSiblingMenus() {
    const parentMenu = this.host.parentElement.closest('groupui-menu');
    Array.from(parentMenu.querySelectorAll('groupui-menu')).forEach((menu) => {
      menu.removeAttribute('visible');
    });
  }

  private handleTriggerClick = () => {
    if (this.isSubmenu()) {
      this.visible = true;
    } else {
      this.visible = !this.visible;
    }
  };

  private handleTriggerOpenKeyDown() {
    if (this.visible && this.isSubmenu()) {
      this.firstMenuItem().focus();
      return;
    }
    this.visible = true;
    this.menuJustOpenedWithKeyboard = true;
  }

  componentDidRender() {
    if (this.menuJustOpenedWithKeyboard && this.isSubmenu()) {
      this.firstMenuItem().focus();
      this.menuJustOpenedWithKeyboard = false;
    }
    if (this.menuJustOpenedWithHover && this.isSubmenu()) {
      this.menuItemsContainer().focus();
      this.menuJustOpenedWithHover = false;
    }
  }

  private menuItemsContainer(): HTMLElement {
    return this.host.shadowRoot.querySelector('#menu-items') as HTMLElement;
  }

  private focusMenuItemsContainerOfParentMenu() {
    const parentMenu = this.host.parentElement.closest('groupui-menu');
    (parentMenu?.shadowRoot.querySelector('#menu-items') as HTMLElement).focus();
  }

  private subscribeToOutsideClicks() {
    this.outsideClick = fromEvent(document, 'click').pipe(takeUntil(this.destroy));
    this.outsideClick.subscribe((event: Event) => {
      this.handleOutsideClick(event);
    });
  }

  private subscribeToMenuMouseLeave() {
    const mouseenter = fromEvent(this.host, 'mouseenter');
    const mouseleave = fromEvent(this.host, 'mouseleave');

    const fire = mouseleave.pipe(
      switchMap(() => {
        return timer(this.delayBeforeCloseOnHover).pipe(takeUntil(merge(mouseenter, this.destroy)));
      })
    );
    fire.subscribe(() => {
      this.visible = false;
    });
  }

  private subscribeToTriggerHover() {
    const mouseenter = fromEvent(this.triggerSlot(), 'mouseenter');
    const mouseleave = fromEvent(this.triggerSlot(), 'mouseleave');

    const longHover = mouseenter
      .pipe(
        switchMap(() => {
          return timer(this.delayBeforeOpenOnHover).pipe(takeUntil(merge(mouseleave, this.destroy)));
        })
      )
      .pipe(takeUntil(this.destroy));

    longHover.subscribe(() => {
      this.menuJustOpenedWithHover = true;
      this.visible = true;
    });
  }

  private subscribeToTriggerClick() {
    const triggerClick = fromEvent(this.triggerSlot(), 'click');

    triggerClick.pipe(takeUntil(this.destroy)).subscribe(() => {
      this.handleTriggerClick();
    });
  }

  private subscribeToTriggerOpenKeyDowns() {
    const arrowRight = fromEvent(this.triggerSlot(), 'keydown').pipe(
      filter((event: KeyboardEvent) => event.key === 'ArrowRight' || event.key === 'Enter' || event.key === ' ')
    );

    arrowRight.pipe(takeUntil(this.destroy)).subscribe(() => {
      this.handleTriggerOpenKeyDown();
    });
  }

  private triggerSlot(): HTMLElement {
    return this.host.shadowRoot.querySelector('[name="trigger"]') as HTMLSlotElement;
  }

  private triggerElement(): HTMLElement {
    return this.host.querySelector('[slot="trigger"]');
  }

  private menuItems(): HTMLGroupuiMenuItemElement[] {
    return Array.from(
      this.host.querySelectorAll(
        ':scope > groupui-menu-item:not([slot="trigger"]), :scope > groupui-menu-group > groupui-menu-item, :scope > groupui-menu > groupui-menu-item[slot="trigger"], :scope > groupui-menu-group > groupui-menu > groupui-menu-item[slot="trigger"]'
      )
    ) as HTMLGroupuiMenuItemElement[];
  }

  private menuGroups(): HTMLGroupuiMenuGroupElement[] {
    return Array.from(this.host.children).filter((element) => {
      return element.tagName === 'GROUPUI-MENU-GROUP';
    }) as HTMLGroupuiMenuGroupElement[];
  }

  private firstMenuItem(): HTMLGroupuiMenuItemElement | null {
    const items = this.menuItems();
    if (items.length > 0) {
      return items[0];
    }
    return null;
  }

  private lastMenuItem(): HTMLGroupuiMenuItemElement | null {
    const items = this.menuItems();
    if (items.length > 0) {
      return items[items.length - 1];
    }
    return null;
  }

  private previousMenuItem(): HTMLGroupuiMenuItemElement {
    const items = this.menuItems();
    const activeItemIndex = items.findIndex((item) => item === document.activeElement);
    if (activeItemIndex === -1 || activeItemIndex === 0) {
      return this.lastMenuItem();
    }
    return items[(activeItemIndex - 1) % items.length];
  }

  private nextMenuItem(): HTMLGroupuiMenuItemElement {
    const items = this.menuItems();
    const activeItemIndex = items.findIndex((item) => item === document.activeElement);
    if (activeItemIndex === -1) {
      return this.firstMenuItem();
    }
    return items[(activeItemIndex + 1) % items.length];
  }

  private handleKeyDown(event: KeyboardEvent) {
    if (event.key === 'ArrowDown') {
      event.preventDefault();
      event.stopPropagation();
      this.nextMenuItem()?.focus();
      return;
    }
    if (event.key === 'ArrowUp') {
      event.preventDefault();
      event.stopPropagation();
      this.previousMenuItem()?.focus();
      return;
    }
    if (event.key === 'Home') {
      event.preventDefault();
      event.stopPropagation();
      this.firstMenuItem()?.focus();
      return;
    }
    if (event.key === 'End') {
      event.preventDefault();
      event.stopPropagation();
      this.lastMenuItem()?.focus();
      return;
    }
    if (event.key === 'ArrowLeft') {
      if (this.isSubmenu()) {
        event.preventDefault();
        event.stopPropagation();
        this.visible = false;
        this.triggerElementForParentMenu()?.focus();
      }
      return;
    }
    if (event.key === 'Escape') {
      this.triggerElement().focus();
      this.visible = false;
    }
    if (event.key === 'Enter') {
      const eventFromMenuGroup = (event.target as HTMLElement).closest('groupui-menu-group:not([mode="multiple"])');
      const isSubmenuTrigger = (event.target as HTMLElement).getAttribute('slot') === 'trigger';
      if (eventFromMenuGroup && !isSubmenuTrigger) {
        this.triggerElement().focus();
        this.visible = false;
      }
    }
    if (event.key === 'Tab') {
      event.preventDefault();
      this.visible = false;
      if (event.shiftKey) {
        const previousFocusableElement = FocusHelper.getPreviousFocusableElement(this.host);
        previousFocusableElement && previousFocusableElement.focus && previousFocusableElement.focus();
      } else {
        const nextFocusableElement = FocusHelper.getNextFocusableElement(this.host);
        nextFocusableElement && nextFocusableElement.focus && nextFocusableElement.focus();
      }
    }
  }

  private defaultSlot(): HTMLSlotElement {
    return this.host.shadowRoot.querySelector('slot:not([name])');
  }

  private isSubmenu(): boolean {
    return this.host.parentElement.closest('groupui-menu') !== null;
  }

  private getStyle() {
    const minWidth = this.minWidth ? { minWidth: this.minWidth } : {};
    const maxHeight = this.maxHeight ? { maxHeight: this.maxHeight } : {};
    return { ...minWidth, ...maxHeight };
  }

  render() {
    return (
      <Host class={{ submenu: this.isSubmenu() }}>
        <groupui-popover
          visible={this.visible}
          full-width={this.fullWidth}
          offset={this.offset}
          placement={this.isSubmenu() ? 'right-start' : this.placement}
        >
          <slot slot="parent" name="trigger"></slot>
          <div
            tabIndex={-1}
            slot="content"
            id="menu-items"
            style={this.getStyle()}
            role="menu"
            aria-expanded={this.visible ? 'true' : 'false'}
          >
            <slot></slot>
          </div>
        </groupui-popover>
      </Host>
    );
  }
}
